import json, re, math
from collections import Counter

manifest='/mnt/data/LSF/baseline_results/officeqa/agentic_codex_qa_gpt54_all/latest_50/logs/latest_50.manifest.json'
with open(manifest) as f:
    man=json.load(f)

MONTHS={m:i for i,m in enumerate(['Jan','Feb','Mar','Apr','May','June','July','Aug','Sept','Oct','Nov','Dec'],1)}
MONTHS_FULL={
    'january':1,'february':2,'march':3,'april':4,'may':5,'june':6,'july':7,'august':8,'september':9,'october':10,'november':11,'december':12,
    'jan':1,'feb':2,'mar':3,'apr':4,'jun':6,'jul':7,'aug':8,'sep':9,'sept':9,'oct':10,'nov':11,'dec':12,
}
ISSUE_Q={'03':'Q1','06':'Q2','09':'Q3','12':'Q4'}
ROW_MONTH_RE=r'(?:Jan|Feb|Mar|Apr|May|June|July|Aug|Sept|Oct|Nov|Dec)[a-z]*\\.?'

def lines_of(path):
    with open(path,encoding='utf-8',errors='ignore') as f:
        return [ln.rstrip('\\n') for ln in f]

def norm(s):
    return s.replace('\\u2014','-').replace('\\u2013','-').replace('\\u00a0',' ').strip()

def is_numtok(s):
    s=norm(s).replace(' ','')
    return bool(re.fullmatch(r'(?:-+|n\\.a\\.|\\*|[+-]?\\d[\\d,]*(?:\\.\\d+)?)', s, re.I))

def clean_numtok(s):
    return norm(s).replace(' ','')

def find_heading(lines, needle):
    n=needle.lower()
    for i,l in enumerate(lines):
        if n in l.lower():
            return i
    return -1

def next_table_or_end(lines, start):
    for i in range(start+1,len(lines)):
        if 'TABLE ' in lines[i] and i>start+1:
            return i
    return len(lines)

def parse_rows(lines, start, end, row_start_fn):
    rows=[]
    i=start
    while i<end:
        s=norm(lines[i])
        if row_start_fn(s):
            label=s
            vals=[]
            j=i+1
            while j<end:
                t=norm(lines[j])
                if row_start_fn(t) or ('TABLE ' in t and j>i+1):
                    break
                if is_numtok(t):
                    vals.append(clean_numtok(t))
                j+=1
            rows.append((label, vals))
            i=j
        else:
            i+=1
    return rows

def annual_row_label(s):
    return bool(re.match(r'"'^'"\\d{4}\\b(?"'!'"\\s*-)', s))

def any_date_row_label(s):
    if re.match(r'"'^'"\\d{4}\\b', s):
        return True
    if re.match(rf'"'^{ROW_MONTH_RE}(?:'"\\s|\\.|"'$)'"', s):
        return True
    return False

def cad_date_label(s):
    return bool(re.match(r'"'^'"\\d{1,2}/\\d{1,2}/\\d{2,4}', s))

def first_table_value_rows(lines, heading_sub, row_fn=annual_row_label):
    h=find_heading(lines, heading_sub)
    if h==-1:
        return []
    e=next_table_or_end(lines,h)
    return parse_rows(lines,h+1,e,row_fn)

def get_profile_text(lines):
    start=-1
    for i,l in enumerate(lines):
        if 'Profile of the Economy' in l:
            start=i
            break
    if start==-1:
        start=0
    end=len(lines)
    for i in range(start+1,len(lines)):
        if 'FEDERAL FISCAL OPERATIONS' in lines[i]:
            end=i
            break
    block='\\n'.join(lines[start:end])
    return block.replace('\\u00a0',' ')

def join_space(text):
    return re.sub(r'\\s+',' ', text)

def fmt_pct(v):
    return v if v.endswith('%') else v+'%'

def signed_pct(num, negative=False):
    s=num
    if negative and not s.startswith('-'):
        s='-'+s
    return fmt_pct(s)

def extract_gdp(profile):
    text=join_space(profile)
    pats=[
        (re.compile(r'Real GDP growth (?:increased|accelerated|rose|advanced|grew|expanded) (?:to )?([0-9]+(?:\\.[0-9]+)?) percent at an annual rate in the ["'^.]{0,80}?quarter'"',re.I), False),
        (re.compile(r'Real GDP growth (?:declined|decreased|fell|contracted) (?:to )?([0-9]+(?:\\.[0-9]+)?) percent at an annual rate in the ["'^.]{0,80}?quarter'"',re.I), True),
        (re.compile(r'According to the ["'^.,;]{0,80}estimate, real GDP (?:advanced|increased|rose|grew|expanded) (?:by |at an annual rate of )?([0-9]+(?:'"\\.[0-9]+)?) percent(?: at an annual rate)? (?:during|in) the ["'^.]{0,80}?quarter'"',re.I), False),
        (re.compile(r'According to the ["'^.,;]{0,80}estimate, real GDP (?:declined|decreased|fell|contracted|dropped) (?:by |at an annual rate of )?([0-9]+(?:'"\\.[0-9]+)?) percent(?: at an annual rate)? (?:during|in) the ["'^.]{0,80}?quarter'"',re.I), True),
        (re.compile(r'real GDP (?:advanced|increased|rose|grew|expanded) ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate during the ["'^.]{0,80}?quarter'"',re.I), False),
        (re.compile(r'real GDP (?:declined|decreased|fell|contracted|dropped) ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate during the ["'^.]{0,80}?quarter'"',re.I), True),
        (re.compile(r'real GDP .*?showed growth of ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate',re.I), False),
        (re.compile(r'real GDP decreased ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate',re.I), True),
    ]
    for pat,neg in pats:
        m=pat.search(text)
        if m:
            return signed_pct(m.group(1), neg)
    return 'NOT_FOUND'

def extract_unemployment(profile):
    text=join_space(profile)
    pats=[
        re.compile(r'In ([A-Z][a-z]+(?: [0-9]{4})?), the unemployment rate ["'^.]*? (?:to|at|stood at|edged down to|ticked down to|ticked up to|rose to|fell to|was) ([0-9]+(?:'"\\.[0-9]+)?) percent',re.I),
        re.compile(r'the unemployment rate ["'^.]*? stood at ([0-9]+(?:'"\\.[0-9]+)?) percent as of ([A-Z][a-z]+(?: [0-9]{4})?)',re.I),
        re.compile(r'the unemployment rate ["'^.]*? reaching ([0-9]+(?:'"\\.[0-9]+)?) percent in ([A-Z][a-z]+(?: [0-9]{4})?)',re.I),
        re.compile(r'unemployment rate declined to ([0-9]+(?:\\.[0-9]+)?) percent in ([A-Z][a-z]+(?: [0-9]{4})?)',re.I),
        re.compile(r'unemployment rate (?:hovered ["'^.]*? and )?stood at ([0-9]+(?:'"\\.[0-9]+)?) percent (?:as of|in) ([A-Z][a-z]+(?: [0-9]{4})?)',re.I),
        re.compile(r'unemployment rate has ["'^.]*? and stood at ([0-9]+(?:'"\\.[0-9]+)?) percent as of ([A-Z][a-z]+ [0-9]{4})',re.I),
    ]
    best=None
    for pat in pats:
        for m in pat.finditer(text):
            if pat.pattern.startswith('In '):
                month_text,val=m.group(1),m.group(2)
            elif 'as of' in pat.pattern or 'stood at' in pat.pattern and pat.groups>=2:
                val,month_text=m.group(1),m.group(2)
            else:
                val,month_text=m.group(1),m.group(2)
            mt=month_text.lower().replace('.', '')
            parts=mt.split()
            mo=MONTHS_FULL.get(parts[0][:4] if parts[0] not in MONTHS_FULL else parts[0], MONTHS_FULL.get(parts[0],0))
            if not mo:
                mo=MONTHS_FULL.get(parts[0],0)
            yr=int(parts[1]) if len(parts)>1 and parts[1].isdigit() else 0
            key=(yr,mo)
            if best is None or key>best[0]:
                best=(key, val)
    if best:
        return fmt_pct(best[1])
    # fallback: first intro statement
    m=re.search(r'unemployment rate ["'^.]{0,80}? ([0-9]+(?:'"\\.[0-9]+)?) percent', text, re.I)
    return fmt_pct(m.group(1)) if m else 'NOT_FOUND'

def comma_int(n):
    return f\"{int(round(n)):,}\"

def extract_payroll(profile):
    text=join_space(profile)
    pats=[
        re.compile(r'average monthly gain of ([0-9,]+) jobs',re.I),
        re.compile(r'averag(?:ed|ing) ([0-9,]+) per month',re.I),
        re.compile(r'averag(?:ed|ing) ([0-9,]+) jobs per month',re.I),
        re.compile(r'added an average of ([0-9,]+) payroll jobs per month',re.I),
        re.compile(r'economy added an average ([0-9,]+) payroll jobs per month',re.I),
        re.compile(r'job creation averaged (?:a solid )?([0-9,]+) per month',re.I),
        re.compile(r'payrolls increased by ([0-9,]+) over the month',re.I), # low confidence, only if question maybe month? avoid unless alone
    ]
    for i,pat in enumerate(pats):
        m=pat.search(text)
        if m:
            # avoid single month fallback unless no other pattern and explicit average absent
            if i==len(pats)-1:
                break
            return m.group(1)
    # compute from totals over months/quarter when explicit average absent
    m=re.search(r'added another ([0-9]+(?:\\.[0-9]+)?) million during the first four months of (\\d{4})', text, re.I)
    if m:
        return comma_int(float(m.group(1))*1_000_000/4)
    m=re.search(r'Over ([A-Z][a-z]+), ([A-Z][a-z]+), and ([A-Z][a-z]+), employers added a total of ([0-9]+(?:\\.[0-9]+)?) million payroll jobs', text, re.I)
    if m:
        return comma_int(float(m.group(4))*1_000_000/3)
    m=re.search(r'In ([0-9]{4}), the economy added an average ([0-9,]+) payroll jobs per month', text, re.I)
    if m:
        return m.group(2)
    return 'NOT_FOUND'

def extract_sentiment(profile):
    text=join_space(profile)
    pats=[
        re.compile(r'(?:Reuters/Michigan|University of Michigan|Michigan consumer sentiment|consumer sentiment index|consumer sentiment survey)["'^.]{0,200}? (?:increasing to|increased to|rose to|reached|stood at|stabilized at|remaining at|at just|at) ([0-9]+(?:'"\\.[0-9]+)?)', re.I),
        re.compile(r'([0-9]+(?:\\.[0-9]+)?) in the preliminary reading for [A-Z][a-z]+ \\d{4}["'^.]{0,80}?(?:Reuters/Michigan|University of Michigan|consumer sentiment)'"', re.I),
    ]
    for pat in pats:
        m=pat.search(text)
        if m:
            return m.group(1)
    return 'NOT_FOUND'

def extract_deficit_pct(profile):
    text=join_space(profile)
    pats=[
        re.compile(r'budget deficit ["'^.]{0,120}? ([0-9]+(?:'"\\.[0-9]+)?) percent of GDP ["'^.]{0,80}?fiscal year ('"\\d{4})', re.I),
        re.compile(r'([0-9]+(?:\\.[0-9]+)?) percent of GDP\\) in fiscal year (\\d{4})', re.I),
        re.compile(r'equal to ([0-9]+(?:\\.[0-9]+)?) percent of GDP', re.I),
        re.compile(r'to ([0-9]+(?:\\.[0-9]+)?) percent in fiscal year (\\d{4})', re.I),
    ]
    best=None
    for pat in pats:
        for m in pat.finditer(text):
            if pat.groups==2:
                pct,yr=m.group(1),int(m.group(2))
            else:
                pct,yr=m.group(1),9999
            if best is None or yr>best[0]:
                best=(yr,pct)
    return fmt_pct(best[1]) if best else 'NOT_FOUND'

def extract_ffo(lines):
    h=find_heading(lines,'TABLE FFO-1')
    if h==-1:
        return 'NOT_FOUND','NOT_FOUND'
    end=next_table_or_end(lines,h)
    for i in range(h,end):
        s=norm(lines[i])
        if s.startswith('Fiscal year ') and 'to date' in s:
            vals=[]
            for j in range(i+1,min(end,i+40)):
                t=norm(lines[j])
                if is_numtok(t):
                    vals.append(clean_numtok(t))
                    if len(vals)>=10:
                        break
            if len(vals)>=7:
                return vals[0], vals[6]
    return 'NOT_FOUND','NOT_FOUND'

def extract_fd1(lines):
    rows=first_table_value_rows(lines,'TABLE FD-1',annual_row_label)
    if not rows:
        return 'NOT_FOUND','NOT_FOUND'
    label,vals=rows[-1]
    gross=vals[0] if len(vals)>=1 else 'NOT_FOUND'
    held=vals[6] if len(vals)>=7 else 'NOT_FOUND'
    return gross, held

def extract_fd5(lines):
    rows=first_table_value_rows(lines,'TABLE FD-5',annual_row_label)
    if not rows:
        return 'NOT_FOUND'
    vals=rows[-1][1]
    return vals[-1] if vals else 'NOT_FOUND'

def extract_fd6(lines):
    h=find_heading(lines,'TABLE FD-6')
    if h==-1:
        return 'NOT_FOUND'
    end=next_table_or_end(lines,h)
    rows=parse_rows(lines,h+1,end,any_date_row_label)
    if not rows:
        return 'NOT_FOUND'
    vals=rows[-1][1]
    if not vals:
        return 'NOT_FOUND'
    lim=vals[0]
    if lim.startswith('-'):
        return 'Suspended'
    return lim

def extract_uscc(lines):
    h=find_heading(lines,'Comparative totals of currency and coins in circulation')
    if h==-1:
        return 'NOT_FOUND'
    # first date row then next two numeric tokens, want 2nd
    for i in range(h+1, min(len(lines), h+40)):
        s=norm(lines[i])
        if re.match(r'"'^[A-Z][a-z]{2,4}'"\\.?(?: \\d{1,2},)? \\d{4}', s) or re.match(r'"'^[A-Z][a-z]{2,4}'"\\. \\d{1,2}, \\d{4}', s):
            vals=[]
            for j in range(i+1, min(len(lines), i+8)):
                t=norm(lines[j])
                if is_numtok(t):
                    vals.append(clean_numtok(t))
                    if len(vals)>=2:
                        return vals[1]
            break
    return 'NOT_FOUND'

def extract_esf(lines):
    h=find_heading(lines,'TABLE ESF-1')
    if h==-1:
        return 'NOT_FOUND'
    end=next_table_or_end(lines,h)
    for i in range(h,end):
        s=norm(lines[i]).lower()
        if s.startswith('total assets'):
            vals=[]
            for j in range(i+1,min(end,i+8)):
                t=norm(lines[j])
                if is_numtok(t):
                    vals.append(clean_numtok(t))
            if vals:
                return vals[-1]
    return 'NOT_FOUND'

def extract_cad(lines):
    h=find_heading(lines,'TABLE FCP-I-1')
    if h==-1:
        return 'NOT_FOUND'
    end=next_table_or_end(lines,h)
    rows=parse_rows(lines,h+1,end,cad_date_label)
    if not rows:
        return 'NOT_FOUND'
    vals=rows[-1][1]
    return vals[-1] if vals else 'NOT_FOUND'

def extract_qtr(doc_name):
    y=doc_name.split('_')[2]
    m=doc_name.split('_')[3]
    return f\"{ISSUE_Q[m]} {y}\"

qs=man['questions']
results={}
missing=Counter()
for d in man['documents']:
    lines=lines_of(d['doc_path'])
    profile=get_profile_text(lines)
    rec={}
    rec[qs[0]]=extract_qtr(d['doc_name'])
    rec[qs[1]]=extract_gdp(profile)
    rec[qs[2]]=extract_unemployment(profile)
    rec[qs[3]]=extract_payroll(profile)
    rec[qs[4]]=extract_sentiment(profile)
    rec[qs[5]]=extract_deficit_pct(profile)
    rec[qs[6]],rec[qs[7]]=extract_ffo(lines)
    rec[qs[8]]=re.search(r'Individual income taxes["'^'"\\n]{0,120}? were \\"'$([0-9]+(?:'"\\.[0-9]+)?) billion', join_space('\\n'.join(lines)), re.I).group(1) if re.search(r'Individual income taxes["'^'"\\n]{0,120}? were \\"'$([0-9]+(?:'"\\.[0-9]+)?) billion', join_space('\\n'.join(lines)), re.I) else 'NOT_FOUND'
    rec[qs[9]],rec[qs[10]]=extract_fd1(lines)
