def lines_of(path):
    with open(path,encoding='utf-8',errors='ignore') as f: return [ln.rstrip('\\n') for ln in f]

def norm(s): return s.replace('\\u2014','-').replace('\\u2013','-').replace('\\u00a0',' ').strip()

def num_tokens(s): return re.findall(r'[+-]?\\d[\\d,]*(?:\\.\\d+)?|n\\.a\\.|-+', s, re.I)

def find_last(lines, needle):
    occ=[i for i,l in enumerate(lines) if needle.lower() in l.lower()]
    return occ[-1] if occ else -1

def profile_lines(lines):
    start=find_last(lines,'Profile of the Economy')
    if start==-1: start=0
    end=len(lines)
    for i in range(start+1,len(lines)):
        if 'FEDERAL FISCAL OPERATIONS' in lines[i]: end=i; break
    return lines[start:end]

def windows(lines, pred, before=1, after=3):
    for i,l in enumerate(lines):
        if pred(l):
            yield i, ' '.join(norm(x) for x in lines[max(0,i-before):min(len(lines),i+after+1)])

def pct(v, neg=False):
    s=v.rstrip('%')
    if neg and not s.startswith('-'): s='-'+s
    return s+'%'

def parse_monthyear(text):
    parts=text.lower().replace('.','').split()
    if not parts: return (0,0)
    mo=MONTHS.get(parts[0],0)
    yr=int(parts[1]) if len(parts)>1 and parts[1].isdigit() else 0
    return (yr,mo)

def extract_gdp(plines):
    # scan windows with real GDP mentions and choose first matching latest-quarter statement
    for _,w in windows(plines, lambda l:'real gdp' in l.lower(), before=1, after=2):
        matches=[]
        for m in re.finditer(r'real GDP(?: growth)? (?:was unexpectedly strong in the ["'^.]*?, )?(?:(?:advanced|increased|rose|grew|expanded|accelerated to)|showed growth of|grew at an annual rate of) ([0-9]+(?:'"\\.[0-9]+)?) percent(?: at an annual rate)? (?:during|in|at) the ([a-z0-9 ]+?quarter)', w, re.I):
            matches.append((m.start(), pct(m.group(1),False)))
        for m in re.finditer(r'real GDP(?: growth)? (?:(?:declined|decreased|fell|contracted|dropped)|was .*?declined) ([0-9]+(?:\\.[0-9]+)?) percent(?: at an annual rate)? (?:during|in|at) the ([a-z0-9 ]+?quarter)', w, re.I):
            matches.append((m.start(), pct(m.group(1),True)))
        for m in re.finditer(r'real GDP(?: growth)? (?:accelerated to|was .*?strong in the ["'^.]*?, rising by) ([0-9]+(?:'"\\.[0-9]+)?) percent at an annual rate',w,re.I):
            matches.append((m.start(), pct(m.group(1),False)))
        # special multi-quarter statements like 2020_09
        for m in re.finditer(r'(?:Real GDP|real GDP) (?:decreased|declined|dropped|contracted) ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate in the ([a-z]+) quarter', w, re.I):
            matches.append((m.start(), pct(m.group(1),True)))
        for m in re.finditer(r'(?:to|at) ([0-9]+(?:\\.[0-9]+)?) percent in the ([a-z]+) quarter', w, re.I):
            pass
        if matches:
            return sorted(matches,key=lambda x:x[0])[-1][1]
        # simpler direct patterns
        m=re.search(r'According to the advance estimate, real GDP (?:advanced|rose|grew|increased) ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate during the [a-z ]+ quarter',w,re.I)
        if m: return pct(m.group(1))
        m=re.search(r'According to the advance estimate, real GDP (?:declined|decreased|fell|dropped|contracted) ([0-9]+(?:\\.[0-9]+)?) percent at an annual rate during the [a-z ]+ quarter',w,re.I)
        if m: return pct(m.group(1),True)
        # generic final capture by last relevant percent in window with real GDP
        if 'annual rate' in w.lower():
            mm=list(re.finditer(r'([0-9]+(?:\\.[0-9]+)?) percent at an annual rate',w,re.I))
            if mm:
                val=mm[-1].group(1)
                prefix=w[max(0,mm[-1].start()-30):mm[-1].start()].lower()
                neg=any(k in prefix for k in ['declin','decreas','fell','drop','contract'])
                return pct(val,neg)
    return 'NOT_FOUND'

def extract_unemployment(plines):
    best=None; fallback=None
    for _,w in windows(plines, lambda l:'unemployment rate' in l.lower() and 'u-6' not in l.lower(), before=1, after=2):
        for pat,order in [
            (r'(?:the )?unemployment rate ["'^.]*? (?:reaching|reached) ([0-9]+(?:'"\\.[0-9]+)?) percent in ([A-Z][a-z]+(?: [0-9]{4})?)', 'val_month'),
            (r'(?:the )?unemployment rate ["'^.]*? stood at ([0-9]+(?:'"\\.[0-9]+)?) percent (?:as of|in) ([A-Z][a-z]+(?: [0-9]{4})?)', 'val_month'),
            (r'(?:the )?unemployment rate (?:declined|edged down|ticked down|rose|fell) to ([0-9]+(?:\\.[0-9]+)?) percent in ([A-Z][a-z]+(?: [0-9]{4})?)', 'val_month'),
            (r'In ([A-Z][a-z]+(?: [0-9]{4})?), the unemployment rate ["'^.]*? (?:to|at|stood at|was) ([0-9]+(?:'"\\.[0-9]+)?) percent', 'month_val'),
            (r'unemployment rate ["'^.]*? and stood at ([0-9]+(?:'"\\.[0-9]+)?) percent as of ([A-Z][a-z]+ [0-9]{4})', 'val_month'),
            (r'unemployment rate stood at ([0-9]+(?:\\.[0-9]+)?) percent', 'val_only'),
            (r'unemployment rate .*? remained elevated at ([0-9]+(?:\\.[0-9]+)?) percent', 'val_only'),
        ]:
            for m in re.finditer(pat,w,re.I):
                if order=='val_month': val,month=m.group(1),m.group(2)
                elif order=='month_val': month,val=m.group(1),m.group(2)
                else:
                    val=m.group(1); month=None
                if month:
                    key=parse_monthyear(month)
                    if best is None or key>best[0]: best=(key,val)
                elif fallback is None:
