            r'The latest labor report for [A-Z][a-z]+ (\\d{4}) showed payrolls increased by ([0-9,]+) over the month',
        ]
        for pat in pats:
            m=re.search(pat,w,re.I)
            if m:
                groups=m.groups()
                if 'thus far' in pat and len(groups)==2:
                    candidates.append(groups[1])
                elif pat.startswith('average pace of payroll job creation slowed'):
                    candidates.append(groups[1])
                elif len(groups)==2 and pat.startswith('In January'):
                    candidates.append(groups[1])
                elif len(groups)==2 and pat.startswith('The latest labor report'):
                    candidates.append(groups[1])
                elif len(groups)==2 and pat.startswith('In (\\\\d{4}),'):
                    # only use if no current-year specific data exists; keep fallback
                    candidates.append(groups[1])
                else:
                    candidates.append(groups[-1])
        m=re.search(r'added another ([0-9]+(?:\\.[0-9]+)?) million during the first four months of (\\d{4})',w,re.I)
        if m: candidates.append(comma_int(float(m.group(1))*1_000_000/4))
        m=re.search(r'added another ([0-9]+(?:\\.[0-9]+)?) million during the first seven months of this year',w,re.I)
        if m: candidates.append(comma_int(float(m.group(1))*1_000_000/7))
        m=re.search(r'Over [A-Z][a-z]+, [A-Z][a-z]+, and [A-Z][a-z]+, employers added a total of ([0-9]+(?:\\.[0-9]+)?) million payroll jobs',w,re.I)
        if m: candidates.append(comma_int(float(m.group(1))*1_000_000/3))
        m=re.search(r'the economy added another ([0-9]+(?:\\.[0-9]+)?) million payroll jobs over the first ([a-z]+) months of (\\d{4})',w,re.I)
        if m:
