def extract_sentiment(plines):
    for _,w in windows(plines, lambda l:any(k in l.lower() for k in ['sentiment','michigan','reuters']), before=1, after=2):
        if 'consumer' not in w.lower() and 'michigan' not in w.lower() and 'reuters' not in w.lower():
            continue
        pats=[
            r'(?:Reuters/Michigan|University of Michigan|Michigan consumer sentiment|consumer sentiment index|consumer sentiment survey)["'^.]{0,200}? (?:increasing to|increased to|rose to|reached|stood at|stabilized at|remaining at|at just|fell to) ([0-9]+(?:'"\\.[0-9]+)?)',
            r'index has ["'^.]{0,120}? stood at ([0-9]+(?:'"\\.[0-9]+)?) in (?:late|early) [A-Z][a-z]+ \\d{4}',
            r'([0-9]+(?:\\.[0-9]+)?) in the preliminary reading for [A-Z][a-z]+ \\d{4}',
            r'reaching ([0-9]+(?:\\.[0-9]+)?)\\.? Since then',
        ]
        for pat in pats:
            m=re.search(pat,w,re.I)
            if m: return m.group(1)
    return 'NOT_FOUND'

def extract_deficit_pct(plines):
    best=None
    for _,w in windows(plines, lambda l:'budget deficit' in l.lower() or ('deficit' in l.lower() and 'gdp' in l.lower()), before=1, after=2):
        for m in re.finditer(r'([0-9]+(?:\\.[0-9]+)?) percent of GDP(?:\\))? (?:in|to) fiscal year (\\d{4})',w,re.I):
            key=int(m.group(2)); val=m.group(1)
            if best is None or key>best[0]: best=(key,val)
        for m in re.finditer(r'\\(([0-9]+(?:\\.[0-9]+)?) percent of GDP\\) in fiscal year (\\d{4})',w,re.I):
            key=int(m.group(2)); val=m.group(1)
            if best is None or key>best[0]: best=(key,val)
        for m in re.finditer(r'budget deficit ["'^.]{0,120}? to ([0-9]+(?:'"\\.[0-9]+)?) percent in fiscal year (\\d{4})',w,re.I):
            key=int(m.group(2)); val=m.group(1)
            if best is None or key>best[0]: best=(key,val)
        m=re.search(r'equal to ([0-9]+(?:\\.[0-9]+)?) percent of GDP',w,re.I)
        if m and best is None: best=(9999,m.group(1))
    return pct(best[1]) if best else 'NOT_FOUND'

def parse_rows(lines,start,end,target_re,stop_fn,label_re,limit=None):
    rows=[]; i=start
    while i<end:
        s=norm(lines[i])
        if re.match(target_re,s):
            tail=re.sub(label_re,'',s,count=1)
            vals=num_tokens(tail)
            j=i+1
            while j<end and (limit is None or len(vals)<limit):
                t=norm(lines[j])
                if stop_fn(t) or ('TABLE ' in t and j>i+1) or re.match(r'"'^'"\\(\\d+\\)',t): break
                vals.extend(num_tokens(t))
                j+=1
            rows.append((s,vals)); i=j
        else: i+=1
    return rows

def any_fd_row(s):
    return bool(re.match(r'"'^'"\\d{4}\\b',s) or re.match(rf'"'^{ROW_MONTH_RE}(?:'"\\s|\\.|"'$)'"',s))

def extract_ffo(lines):
    h=find_last(lines,'TABLE FFO-1')
    if h==-1: return 'NOT_FOUND','NOT_FOUND'
    end=next((i for i in range(h+1,len(lines)) if 'TABLE FFO-2' in lines[i]),len(lines))
    for i in range(h,end):
        s=norm(lines[i])
        if s.startswith('Fiscal year ') and 'to date' in s:
            tail=re.sub(r'"'^Fiscal year '"\\d{4}(?: year)? to date[ .]*','',s)
            vals=num_tokens(tail)
            j=i+1
            while j<end and len(vals)<10:
                t=norm(lines[j])
                if re.match(rf'"'^(?:Fiscal year|'"\\d{{4}}\\s*-|{ROW_MONTH_RE})(?:\\s|\\.|"'$)'"',t): break
                vals.extend(num_tokens(t)); j+=1
            if len(vals)>=10: return vals[0],vals[6]
    return 'NOT_FOUND','NOT_FOUND'

def extract_fd1(lines):
    h=find_last(lines,'TABLE FD-1')
    if h==-1: return 'NOT_FOUND','NOT_FOUND'
    end=next((i for i in range(h+1,len(lines)) if 'TABLE FD-2' in lines[i]),len(lines))
    rows=parse_rows(lines,h+1,end,r'"'^'"\\d{4}\\b(?"'!'"\\s*-)',any_fd_row,r'"'^'"\\d{4}\\b(?"'!'"\\s*-)[ .]*')
    rows=[r for r in rows if len(r[1])>=9 and int(r[1][1].replace(',',''))>1000000]
    if not rows: return 'NOT_FOUND','NOT_FOUND'
    vals=rows[-1][1]
    return vals[0],vals[6]

def extract_fd5(lines):
