def extract_uscc(lines):
    h=find_last(lines,'Comparative totals of currency and coins in circulation')
    if h==-1: return 'NOT_FOUND'
    for i in range(h+1,min(len(lines),h+40)):
        s=norm(lines[i])
        if re.match(r'"'^[A-Z][a-z]{2,4}'"\\.?(?: \\d{1,2},)? \\d{4}',s):
            vals=num_tokens(s)
            j=i+1
            while j<min(len(lines),i+8) and len(vals)<3:
                vals.extend(num_tokens(norm(lines[j]))); j+=1
            # first token may be year from date? current line num_tokens includes day/year. use following numeric tokens only from subsequent lines.
            seq=[]
            for k in range(i+1,min(len(lines),i+8)):
                seq.extend(num_tokens(norm(lines[k])))
                if len(seq)>=2: return seq[1]
    return 'NOT_FOUND'

def extract_esf(lines):
    idxs=[i for i,l in enumerate(lines) if norm(l).lower().startswith('total assets')]
    if not idxs: return 'NOT_FOUND'
