ROW_MONTH_RE=r'(?:Jan|Feb|Mar|Apr|May|June|July|Aug|Sept|Oct|Nov|Dec)[a-z]*\\.?'

def lines_of(path):
    with open(path,encoding='utf-8',errors='ignore') as f:
        return [ln.rstrip('\\n') for ln in f]

def norm(s):
    return s.replace('\\u2014','-').replace('\\u2013','-').replace('\\u00a0',' ').strip()

def num_tokens(s):
    return re.findall(r'[+-]?\\d[\\d,]*(?:\\.\\d+)?|n\\.a\\.|-+', s, re.I)

def find_last(lines, needle):
    occ=[i for i,l in enumerate(lines) if needle.lower() in l.lower()]
    return occ[-1] if occ else -1

def parse_rows(lines,start,end,target_re,stop_fn,label_re,limit=None):
    rows=[]; i=start
    while i<end:
        s=norm(lines[i])
        if re.match(target_re,s):
            tail=re.sub(label_re,'',s,count=1)
            vals=num_tokens(tail)
            j=i+1
            while j<end and (limit is None or len(vals)<limit):
                t=norm(lines[j])
                if stop_fn(t) or ('TABLE ' in t and j>i+1) or re.match(r'"'^(?:'"\\(|\\*|Note)',t):
                    break
                vals.extend(num_tokens(t))
                j+=1
            rows.append((s,vals))
            i=j
        else:
            i+=1
    return rows

def any_fd_row(s):
    return bool(re.match(r'"'^'"\\d{4}\\b',s) or re.match(rf'"'^{ROW_MONTH_RE}(?:'"\\s|\\.|"'$)'"',s))

def extract_ffo(lines):
    h=find_last(lines,'TABLE FFO-1')
