        return 'NOT_FOUND','NOT_FOUND'
    end=next((i for i in range(h+1,len(lines)) if 'TABLE FFO-2' in lines[i]),len(lines))
    for i in range(h,end):
        s=norm(lines[i])
        if s.startswith('Fiscal year ') and 'to date' in s:
            tail=re.sub(r'"'^Fiscal year '"\\d{4}(?: year)? to date[ .]*','',s)
            vals=num_tokens(tail)
            j=i+1
            while j<end and len(vals)<10:
                t=norm(lines[j])
                if re.match(rf'"'^(?:Fiscal year|'"\\d{{4}}\\s*-|{ROW_MONTH_RE})(?:\\s|\\.|"'$)'"',t):
