    rows=parse_rows(lines,h+1,end,r'"'^(?:'"\\d{4}\\s*[-–]\\s*'+ROW_MONTH_RE+r'|\\d{4}\\b(?"'!'"\\s*-)|'+ROW_MONTH_RE+r')',any_fd_row,r'"'^(?:'"\\d{4}\\s*[-–]\\s*'+ROW_MONTH_RE+r'|\\d{4}\\b(?"'!'"\\s*-)|'+ROW_MONTH_RE+r')[ .-]*')
